			id = "forever/class/druid/bear-form",
			pack = "guides",
			title = "{spell:5487} and {area:493}",
			classes = { "DRUID" },
			minLevel = 10,
			maxLevel = 12,
			category = "Class",
			folder = "Druid",
			keywords = { "Bear Form", "Teleport: Moonglade", "Moonglade", "Heeding the Call", "Great Bear Spirit", "Body and Heart", "Moonkin Stone", "Lunaclaw", "Child of Nature", "Great Ursera Spirit", "Strength and Mercy", "Ur'endra", "Skyborne", "class quest" },
			reward = { { spell = 5487, spellName = "Bear Form" } },
			why = "Your tanking form: Forever no longer trains {spell:5487}, these quests give it. Opens {area:493} too.",
			zone = 1450,
			zoneName = "Moonglade",
			author = "Polestar",
			version = 1,
			names = { ["area:1638"] = "Thunder Bluff", ["area:1639"] = "Elder Rise", ["area:1658"] = "Cenarion Enclave", ["area:16623"] = "Shen'dar Highlands", ["area:16626"] = "Gustberry Lowlands", ["area:16629"] = "Shrine of Akir", ["area:16638"] = "Valanaar", ["area:17045"] = "Skywatcher Plateau", ["area:186"] = "Dolanaar", ["area:222"] = "Bloodhoof Village", ["area:2361"] = "Nighthaven", ["area:279"] = "Dalaran", ["area:378"] = "Camp Taurajo", ["area:442"] = "Auberdine", ["area:493"] = "Moonglade", ["area:702"] = "Rut'theran Village", ["item:15208"] = "Cenarion Moondust", ["item:15710"] = "Cenarion Lunardust", ["npc:10897"] = "Sindrayl", ["npc:11798"] = "Bunthen Plainswind", ["npc:11800"] = "Silva Fil'naveth", ["npc:11802"] = "Dendrite Starblaze", ["npc:12144"] = "Lunaclaw Spirit", ["npc:252359"] = "Lotheluum Starbreeze", ["npc:2543"] = "Archmage Ansirem Runeweaver", ["npc:255853"] = "Urs'endris", ["npc:258443"] = "Ur'endra", ["npc:259084"] = "Denaaris Stargale", ["npc:259118"] = "Muln Earthfury", ["npc:270459"] = "Alfina Nightgaze", ["npc:3033"] = "Turak Runetotem", ["npc:3064"] = "Gennia Runetotem", ["npc:3602"] = "Kal", ["npc:4217"] = "Mathrengyl Bearwalker", ["npc:5504"] = "Sheldras Moontree", ["npc:6746"] = "Innkeeper Pala", ["npc:6929"] = "Innkeeper Gryshka", ["object:177525"] = "Moonkin Stone", ["quest:5922"] = "Moonglade", ["quest:5923"] = "Heeding the Call", ["quest:5926"] = "Heeding the Call", ["quest:5929"] = "Great Bear Spirit", ["quest:5930"] = "Great Bear Spirit", ["quest:5931"] = "Back to Darnassus", ["quest:5932"] = "Back to Thunder Bluff", ["quest:6001"] = "Body and Heart", ["quest:6002"] = "Body and Heart", ["quest:94638"] = "Strength and Mercy", ["quest:94911"] = "Child of Nature", ["quest:94912"] = "Child of Nature", ["spell:18960"] = "Teleport: Moonglade", ["spell:5487"] = "Bear Form", ["zone:1412"] = "Mulgore", ["zone:1413"] = "Barrens", ["zone:1453"] = "Stormwind", ["zone:1454"] = "Orgrimmar", ["zone:1456"] = "Thunder Bluff", ["zone:1457"] = "Darnassus", ["zone:2521"] = "Zephras Isle" },
			written = { ["Cast {spell:18960}: it lands you beside the building where {npc:11802} stands upstairs, past the armor vendor. The {quest:5929} sits in the woods to the north-west. Speak to it and go through all of its words (what it represents, the strength of the body, the strength of the heart, then ask for its blessing): the talk is the objective, there is no fight. It blends into the ground, has no quest mark and gives off a faint blue-grey glow by a group of three trees: from {area:2361} go west along the foot of the northern mountains, through the gap between the trees and the hills. If {npc:11802} is missing when you return, step outside and cast {spell:18960} again. Learn the {area:493} flight path ({npc:10897}, south of the lake) for later, then take {npc:11800}'s flight from the middle of {area:2361}: she flies druids straight to {area:702}, no flight path needed. Take the portal up to {zone:1457}."] = "Cast Teleport: Moonglade: it lands you beside the building where Dendrite Starblaze stands upstairs, past the armor vendor. The Great Bear Spirit sits in the woods to the north-west. Speak to it and go through all of its words (what it represents, the strength of the body, the strength of the heart, then ask for its blessing): the talk is the objective, there is no fight. It blends into the ground, has no quest mark and gives off a faint blue-grey glow by a group of three trees: from Nighthaven go west along the foot of the northern mountains, through the gap between the trees and the hills. If Dendrite is missing when you return, step outside and cast Teleport: Moonglade again. Learn the Moonglade flight path (Sindrayl, south of the lake) for later, then take Silva Fil'naveth's flight from the middle of Nighthaven: she flies druids straight to Rut'theran Village, no flight path needed. Take the portal up to Darnassus.", ["Cast {spell:18960}: it lands you beside the building where {npc:11802} stands upstairs. The {quest:5930} sits in the woods to the north-west. Speak to it and go through all of its words (what it represents, the strength of the body, the strength of the heart, then ask for its blessing): the talk is the objective, there is no fight. It blends into the ground, has no quest mark and gives off a faint blue-grey glow by a group of three trees: from {area:2361} go west along the foot of the northern mountains, through the gap between the trees and the hills. If {npc:11802} is missing when you return, step outside and cast {spell:18960} again. Learn the {quest:5922} flight path (Faustron, south-west of the lake); {npc:11798} in {area:2361} flies druids to {area:1638}."] = "Cast Teleport: Moonglade: it lands you beside the building where Dendrite Starblaze stands upstairs. The Great Bear Spirit sits in the woods to the north-west. Speak to it and go through all of its words (what it represents, the strength of the body, the strength of the heart, then ask for its blessing): the talk is the objective, there is no fight. It blends into the ground, has no quest mark and gives off a faint blue-grey glow by a group of three trees: from Nighthaven go west along the foot of the northern mountains, through the gap between the trees and the hills. If Dendrite is missing when you return, step outside and cast Teleport: Moonglade again. Learn the Moonglade flight path (Faustron, south-west of the lake); Bunthen Plainswind in Nighthaven flies druids to Thunder Bluff.", ["Fly back to {area:702} and take the portal up to {npc:4217}."] = "Fly back to Rut'theran Village and take the portal up to Mathrengyl." },
			steps = {
				{
					title = "{quest:5923}",
					note = "At 10 a druid's call reaches you: {npc:3602} in {area:186}, Denatharion in {zone:1457} or Theridran in {zone:1453}. Any one of them sends you to {npc:4217} in the Cenarion Enclave of Darnassus.",
					only = { races = { "NightElf" } },
					goals = {
						{ t = "level", level = 10 },
						{ t = "accept", quest = 5925, title = "Heeding the Call", npc = 3602, npcName = "Kal", minLevel = 10, qlvl = 10, closedBy = { 5921, 5923, 5924 }, preTitles = { [5921] = "Moonglade", [5923] = "Heeding the Call", [5924] = "Heeding the Call" }, map = 1438, x = 55.95, y = 61.56, z = 1293.8, f = "e", optional = true, note = "{npc:3602}, {area:186}; Denatharion's and Theridran's letters lead to the same place" },
					},
				},
				{
					title = "{npc:4217}",
					note = "{npc:4217} stands upstairs in the druids' building of the {area:1658}. He teaches you {spell:18960} with the quest (it stays in your spellbook, Balance tab).",
					only = { races = { "NightElf" } },
