						{ t = "accept", quest = 1954, title = "The Infernal Orb", npc = 6546, npcName = "Tabetha", minLevel = 35, qlvl = 40, map = 1445, x = 46.06, y = 57.09, z = 39, f = "e" },
					},
				},
				{
					title = "{quest:1954}",
					note = "The Burning Blade Summoners (level 38-39, not elite) work the {area:602} in southern {zone:1443}, east of {area:2408}, and every one carries an {item:7291}. They cast {spell:686} from 40 yards, keep an imp at their side and run for help at low health; Nether Maidens patrol the pillared ruin beside them, so pull with care. Horde mages: one more summoner stands alone in western {zone:1412}, south-west of {zone:1456}.",
					goals = {
						{ t = "collect", quest = 1954, title = "The Infernal Orb", item = 7291, itemName = "Infernal Orb", count = 1, oi = 1, map = 1443, x = 66.49, y = 77.94, f = "e", spotsPacked = "54.9,71.7,,58,1;50.3,72.3,,58,1;49.6,77.2,,58,1;52.7,80.2,,75,3;80.5,77.1,,58,3;81.2,80.8,,80,3", spread = true, lvl = 39, note = "{item:7291}: {npc:4668}", from = "Burning Blade Summoner", fromKind = "npc", fromId = 4668, fromNpcs = { { npc = 4668, npcName = "Burning Blade Summoner" } } },
					},
				},
				{
					title = "{quest:1955}",
					note = "Back at {npc:6546}'s. Kill the critters around the cottage first: they join the fight. Accepting {quest:1955} starts a 3 minute timer, and {npc:6546} calls the {npc:6549} out in her garden: a level 40 elite that resists many spells, roots and slows. Grouping up is encouraged: a mage of 40 may need help or potions, at about 45 it is soloable. You can pull it from range from the dock. The timer keeps running after it dies, so hand the quest in straight away. If time runs out, abandon the quest and take it again; she calls the demon again.",
					goals = {
						{ t = "turnin", quest = 1954, title = "The Infernal Orb", npc = 6546, npcName = "Tabetha", map = 1445, x = 46.06, y = 57.09, z = 39, f = "e" },
