					note = "{npc:7311}, one of {zone:1454}'s mage trainers in {object:173161}, gives it; so do {npc:4567} in the {zone:1458} and {npc:3047} in {zone:1456}.",
					only = { factions = { "Horde" } },
					goals = {
						{ t = "level", level = 50 },
						{ t = "accept", quest = 8250, title = "Magecraft", npc = 7311, npcName = "Uthel'nay", minLevel = 50, qlvl = 52, map = 1454, x = 39.16, y = 86.27, z = 43, f = "e" },
					},
				},
				{
					title = "{npc:8395}",
					note = "Fly to {area:3137} (Alliance) or {area:1237} (Horde). {npc:8395} camps below his master's tower, a short way east of {area:1237}: from the fork of {zone:1447}'s main road at the {area:1221}, head straight north to the cliffs. Get off your mount before he teleports you up, or the teleport may not take you. A trail with no enemies climbs to {npc:8379} at the top of the tower; an attendant at the top sends you back down, as often as you like.",
					goals = {
						{ t = "turnin", quest = 8250, title = "Magecraft", npc = 8395, npcName = "Sanath Lim-yo", map = 1447, x = 28.11, y = 50.09, z = 121.1, f = "e" },
