					},
				},
				{
					title = "{npc:8379}",
					note = "Back to {npc:8395}, who teleports you up to the tower.",
					goals = {
						{ t = "turnin", quest = 8251, title = "Magic Dust", npc = 8379, npcName = "Archmage Xylem", map = 1447, x = 29.25, y = 40.21, z = 304.8, f = "e" },
						{ t = "accept", quest = 8252, title = "The Siren's Coral", npc = 8379, npcName = "Archmage Xylem", minLevel = 50, qlvl = 52, pre = { 8251 }, preTitles = { [8251] = "Magic Dust" }, map = 1447, x = 29.25, y = 40.21, z = 304.8, f = "e" },
					},
				},
				{
					title = "{item:20029}",
					note = "The Spitelash Sirens (level 50-52) walk the ruins and beaches around the {area:1221} and the bay east of {area:1237}, often three together, and a few stand inside the {area:1223}; each drops a coral about one time in four. The Spitelash Screamers look almost the same but never drop it. Killing the other naga there makes more Sirens appear in their spots. {npc:7864} ghosts wander the ruins: watch your back.",
					goals = {
						{ t = "collect", quest = 8252, title = "The Siren's Coral", item = 20029, itemName = "Enchanted Coral", count = 6, oi = 1, map = 1447, x = 36.33, y = 48.02, f = "e", spotsPacked = "36.9,49,,65,4;41,53.1,,91,5;44.8,50.9,,66,4;47.7,47.2,,48,1;50.2,43.1,,48,1;45,42.6,,78,4;48.6,57.1,,59,4;46.1,61.6,,49,3;42.6,64.1,,55,3;39.2,61.3,,56,4;35.5,58.8,,48,1;49.8,64.3,,48,2;39.3,47.1,,48,3,1;38.6,51.8,,61,3,1;35.2,54,,83,7,1;38.6,55.8,,87,8,1;43.3,46.1,,48,2,1;44.7,54,,48,3,1;45.6,47.5,,48,1,1;44.9,57.1,,67,5,1;46.4,39.8,,48,1,1;47.8,50.7,,78,5,1;48.1,45.1,,75,4,1;46.3,59.4,,48,2,1;49.2,53.3,,48,2,1;49.5,60.2,,48,1,1;47.8,64.5,,89,7,1", spread = true, lvl = 52, note = "{item:20029}: {npc:6195}", from = "Spitelash Siren", fromKind = "npc", fromId = 6195, fromNpcs = { { npc = 6195, npcName = "Spitelash Siren" } } },
					},
				},
				{
					title = "{npc:8379} again",
					note = "Back to {npc:8395} and up to the tower.",
					goals = {
						{ t = "turnin", quest = 8252, title = "The Siren's Coral", npc = 8379, npcName = "Archmage Xylem", map = 1447, x = 29.25, y = 40.21, z = 304.8, f = "e" },
						{ t = "accept", quest = 8253, title = "Destroy Morphaz", npc = 8379, npcName = "Archmage Xylem", minLevel = 50, qlvl = 52, pre = { 8252 }, preTitles = { [8252] = "The Siren's Coral" }, map = 1447, x = 29.25, y = 40.21, z = 304.8, f = "e" },
					},
				},
				{
					title = "Morphaz",
					note = "{area:1477}, the {area:1417}, lies in the {area:74}: climb the steps into the sunken building, swim down through it and follow the passage down to the portal. A group of five, level 50-54. Morphaz is not waiting when you arrive. First kill the six troll guardians (elites of 50-52) on the platforms around the upper ring; that opens the way down (the left-hand ramp from the entrance) to {npc:5710} and {npc:5711} in the Pit of Sacrifice. Once Jammal'an dies, two green drakes, Weaver and Dreamscythe, come out and patrol the pit: pull them one at a time. When both are dead, Morphaz (level 52 elite, {spell:12533} and {spell:11019}) and Hazzas appear together and cannot be split, so fight both. The shard always drops. Hunters, Priests and Rogues of 50 need Morphaz too: a group of them shares one clear.",
					goals = {
						{ t = "collect", quest = 8253, title = "Destroy Morphaz", item = 20085, itemName = "Arcane Shard", count = 1, oi = 1, map = 1435, x = 69.9, y = 53.6, f = "e", note = "{item:20085}: Morphaz", group = { kind = "elite", rank = 1 } },
					},
				},
				{
					title = "The {item:20085}",
					note = "Back to {zone:1447}, {npc:8395} and the tower. Look at the reward window before you hand in: Classic offered the {item:20037}, the {item:20036} or the {item:20035}, and Forever's notes say the choice may be gone.",
					goals = {
						{ t = "turnin", quest = 8253, title = "Destroy Morphaz", npc = 8379, npcName = "Archmage Xylem", map = 1447, x = 29.25, y = 40.21, z = 304.8, f = "e" },
					},
				},
			},
		})
	end
	register()
end

