			zone = 1447,
			zoneName = "Azshara",
			author = "Polestar",
			version = 1,
			names = { ["area:1221"] = "Ruins of Eldarath", ["area:1223"] = "Temple of Zin-Malor", ["area:1237"] = "Valormok", ["area:3137"] = "Talrendis Point", ["item:23250"] = "Prismatic Shell", ["npc:16479"] = "Polymorph Clone", ["npc:8379"] = "Archmage Xylem", ["npc:8395"] = "Sanath Lim-yo", ["npc:8408"] = "Warlord Krellian", ["quest:9364"] = "Fragmented Magic", ["spell:118"] = "Polymorph", ["spell:122"] = "Frost Nova", ["spell:1449"] = "Arcane Explosion", ["spell:28272"] = "Polymorph: Pig", ["spell:99"] = "Demoralizing Roar", ["zone:1447"] = "Azshara" },
			steps = {
				{
					title = "{npc:8395}",
					note = "Fly to {area:3137} (Alliance) or {area:1237} (Horde). {npc:8395} camps below {npc:8379}'s tower, a short way east of {area:1237}: from the fork of {zone:1447}'s main road at the {area:1221}, head straight north to the cliffs. Dismount, and he teleports you up; a trail climbs to the Archmage at the top of the tower.",
					goals = {
						{ t = "level", level = 60 },
						{ t = "accept", quest = 9362, title = "Warlord Krellian", npc = 8379, npcName = "Archmage Xylem", minLevel = 60, qlvl = 60, map = 1447, x = 29.25, y = 40.21, z = 304.8, f = "e" },
					},
				},
				{
					title = "{npc:8408}",
					note = "{npc:8408} (level 55, not elite, Strike and {spell:99}) hides behind his Spitelash guards in the {area:1223}, the biggest building in the middle of the {area:1221}. He always drops the {item:23250} and is back 5 1/2 minutes after a kill. Leave any raid group first: a raid gets no credit, a party is fine.",
					goals = {
						{ t = "collect", quest = 9362, title = "Warlord Krellian", item = 23250, itemName = "Prismatic Shell", count = 1, oi = 1, map = 1447, x = 41.02, y = 53.05, f = "e", note = "{item:23250}: {npc:8408}", from = "Warlord Krellian", fromKind = "npc", fromId = 8408, fromNpcs = { { npc = 8408, npcName = "Warlord Krellian" } } },
					},
				},
				{
					title = "{npc:8379}",
					note = "Back to {npc:8395} and up to the tower. Xylem hands the shell back with the next quest: keep it in your bags.",
