			collects = { 18608 },
			reward = { { item = 18608, itemName = "Benediction" }, { item = 18659, itemName = "Splinter of Nordrassil" } },
			why = "The epic priest staff: the {spell:23101} from {area:2717}, {npc:14494}'s peasant rescue, then the Eye of Shadow.",
			zone = 1423,
			zoneName = "Eastern Plaguelands",
			author = "Polestar",
			version = 1,
			group = true,
			names = { ["area:1584"] = "Blackrock Depths", ["area:2279"] = "Stratholme", ["area:254"] = "Blackrock Mountain", ["area:2717"] = "Molten Core", ["item:13180"] = "Stratholme Holy Water", ["item:13444"] = "Major Mana Potion", ["item:13931"] = "Nightfin Soup", ["item:18412"] = "Core Fragment", ["item:18608"] = "Benediction", ["item:18646"] = "The Eye of Divinity", ["item:18659"] = "Splinter of Nordrassil", ["item:18665"] = "The Eye of Shadow", ["item:20520"] = "Dark Rune", ["item:8956"] = "Oil of Immolation", ["npc:12018"] = "Majordomo Executus", ["npc:12396"] = "Doomguard Commander", ["npc:12397"] = "Lord Kazzak", ["npc:14387"] = "Lothos Riftwaker", ["npc:14494"] = "Eris Havenfire", ["object:179694"] = "Death Post", ["object:179703"] = "Cache of the Firelord", ["quest:7621"] = "A Warning", ["quest:7622"] = "The Balance of Light and Shadow", ["spell:139"] = "Renew", ["spell:15237"] = "Holy Nova", ["spell:2061"] = "Flash Heal", ["spell:23101"] = "Eye of Divinity", ["spell:552"] = "Abolish Disease", ["zone:1419"] = "Blasted Lands", ["zone:1423"] = "Eastern Plaguelands" },
			written = { ["Save 50 peasants before 15 die (the {object:179694} by the path counts the dead). They walk from the cave towards {npc:14494} in waves, catch diseases and draw skeletons and skeleton archers. Cure the purple-glowing diseases first ({spell:552}), keep {spell:139} on the hurt ones, {spell:2061} the nearly dead, and kill skeletons as they spawn: one {spell:15237} of rank 3 or more kills them, oil takes two ticks while they hit you. Shield yourself at the start of each wave; friendly nameplates make the hurt peasants easy to pick out. Friends may buff you before you accept and may heal or cure peasants, but they must not heal or buff you, attack a skeleton or bring a pet once it starts, or a demon appears and kills everyone. Fail, and {npc:14494} is gone for a while (players report anything from 15 minutes to two hours); talk to her again when she is back."] = "Save 50 peasants before 15 die (the Death Post by the path counts the dead). They walk from the cave towards Eris in waves, catch diseases and draw skeletons and skeleton archers. Cure the purple-glowing diseases first (Abolish Disease), keep Renew on the hurt ones, Flash Heal the nearly dead, and kill skeletons as they spawn: one Holy Nova of rank 3 or more kills them, oil takes two ticks while they hit you. Shield yourself at the start of each wave; friendly nameplates make the hurt peasants easy to pick out. Friends may buff you before you accept and may heal or cure peasants, but they must not heal or buff you, attack a skeleton or bring a pet once it starts, or a demon appears and kills everyone. Fail, and Eris is gone for a while (players report anything from 15 minutes to two hours); talk to her again when she is back.", ["The epic priest staff: the {spell:23101} from {area:2717}, {npc:14494}'s peasant rescue, then the Eye of Shadow."] = "The epic priest staff: the Eye of Divinity from Molten Core, Eris's peasant rescue, then the Eye of Shadow.", ["{item:18646} comes from the {object:179703}, the chest that appears when {npc:12018} yields in {area:2717}, a 40-player raid (it is in the cache about half the time). {area:2717}'s portal is at the bottom of {area:1584}; once you have done Attunement to the Core (a {item:18412} from beside that portal), {npc:14387} inside {area:254} ports you straight in. Nothing in this chain starts without the Eye: {npc:14494} is invisible until you equip it."] = "The Eye of Divinity comes from the Cache of the Firelord, the chest that appears when Majordomo Executus yields in Molten Core, a 40-player raid (it is in the cache about half the time). Molten Core's portal is at the bottom of Blackrock Depths; once you have done Attunement to the Core (a Core Fragment from beside that portal), Lothos Riftwaker inside Blackrock Mountain ports you straight in. Nothing in this chain starts without the Eye: Eris is invisible until you equip it." },
			steps = {
				{
					title = "{item:18646}",
					note = "{item:18646} comes from the {object:179703}, the chest that appears when {npc:12018} yields in {area:2717}, a 40-player raid (it is in the cache about half the time). {area:2717}'s portal is at the bottom of {area:1584}; once you have done Attunement to the Core (a {item:18412} from beside that portal), {npc:14387} inside {area:254} ports you straight in. Nothing in this chain starts without the Eye: {npc:14494} is invisible until you equip it.",
					goals = {
						{ t = "talk", npc = 14387, npcName = "Lothos Riftwaker", map = 1428, x = 26.4, y = 24.5, z = 181, f = "e", optional = true, note = "{npc:14387}: the way into {area:2717} once attuned" },
						{ t = "collect", item = 18646, itemName = "The Eye of Divinity", count = 1, map = 1428, x = 26.4, y = 24.5, f = "e", note = "{item:18646}: {area:2717}, through {area:254}", group = { kind = "group", size = 40 } },
					},
				},
				{
					title = "{npc:14494}",
					note = "Equip {item:18646}, then find {npc:14494}, a ghost on the hillside in the north-west of the {zone:1423}, west of {area:2279}'s gate (if she does not show, take the Eye off and put it back on). {quest:7621} is only talk; {quest:7622} starts the moment you accept it, so prepare first: full mana, Major Mana Potions, Demonic or Dark Runes, mana food or {item:13931}, and a stack of {item:8956} or {item:13180} for the skeletons.",
					goals = {
						{ t = "level", level = 60 },
						{ t = "accept", quest = 7621, title = "A Warning", npc = 14494, npcName = "Eris Havenfire", minLevel = 60, qlvl = 60, map = 1423, x = 17.21, y = 12.79, z = 164.4 },
						{ t = "turnin", quest = 7621, title = "A Warning", npc = 14494, npcName = "Eris Havenfire", map = 1423, x = 17.21, y = 12.79, z = 164.4 },
						{ t = "accept", quest = 7622, title = "The Balance of Light and Shadow", npc = 14494, npcName = "Eris Havenfire", minLevel = 60, qlvl = 60, pre = { 7621 }, preTitles = { [7621] = "A Warning" }, map = 1423, x = 17.21, y = 12.79, z = 164.4 },
					},
				},
				{
					title = "{quest:7622}",
					note = "Save 50 peasants before 15 die (the {object:179694} by the path counts the dead). They walk from the cave towards {npc:14494} in waves, catch diseases and draw skeletons and skeleton archers. Cure the purple-glowing diseases first ({spell:552}), keep {spell:139} on the hurt ones, {spell:2061} the nearly dead, and kill skeletons as they spawn: one {spell:15237} of rank 3 or more kills them, oil takes two ticks while they hit you. Shield yourself at the start of each wave; friendly nameplates make the hurt peasants easy to pick out. Friends may buff you before you accept and may heal or cure peasants, but they must not heal or buff you, attack a skeleton or bring a pet once it starts, or a demon appears and kills everyone. Fail, and {npc:14494} is gone for a while (players report anything from 15 minutes to two hours); talk to her again when she is back.",
					goals = {
						{ t = "complete", quest = 7622, title = "The Balance of Light and Shadow", objs = { { text = "The Balance of Light and Shadow", count = 1 } } },
					},
				},
				{
					title = "{item:18608}",
					goals = {
						{ t = "turnin", quest = 7622, title = "The Balance of Light and Shadow", npc = 14494, npcName = "Eris Havenfire", map = 1423, x = 17.21, y = 12.79, z = 164.4, note = "{npc:14494}: {item:18659}", rewards = { items = { { item = 18659, itemName = "Splinter of Nordrassil" } } } },
					},
				},
				{
					title = "{item:18665}",
					note = "The splinter needs {item:18665} as well. {npc:12397}, a world boss in the {zone:1419} (a raid), always drops it; Manahounds and Doomguard Commanders there drop it rarely (about 3% and 2%), the Hederine of Winterspring hardly ever. It can be traded: check the Auction House first.",
					goals = {
						{ t = "collect", item = 18665, itemName = "The Eye of Shadow", count = 1, map = 1419, x = 35.54, y = 74.98, f = "e", from = "Lord Kazzak", fromKind = "npc", fromRank = 3, fromId = 12397, fromNpcs = { { npc = 12397, npcName = "Lord Kazzak" } }, group = { kind = "elite", rank = 3 } },
					},
				},
				{
					title = "{item:18608}",
					note = "With the {item:18659}, {item:18646} and {item:18665} in your bags, use the splinter wherever you are: it becomes {item:18608}. Use {item:18608} to turn it into Anathema, the shadow staff, and back (a 30-minute cooldown).",
					goals = {
