						{ t = "accept", quest = 6701, title = "Syndicate Emblems", npc = 6766, npcName = "Ravenholdt Guard", minLevel = 24, qlvl = 60, pre = { 6681 }, preTitles = { [6681] = "The Manor, Ravenholdt" }, map = 1416, x = 85.27, y = 79.56, z = 195.5, f = "e", spotsPacked = "85,79.2,195.5,17,4;81.7,77.5,173.9,15,2;82.4,73.8,168.5,15,1,1", optional = true, note = "{npc:6766}: {quest:6701}, repeatable" },
						{ t = "turnin", quest = 6701, title = "Syndicate Emblems", npc = 6766, npcName = "Ravenholdt Guard", map = 1416, x = 85.27, y = 79.56, z = 195.5, f = "e", spotsPacked = "85,79.2,195.5,17,4;81.7,77.5,173.9,15,2;82.4,73.8,168.5,15,1,1", optional = true, note = "one emblem each time, 100 reputation" },
					},
				},
				{
					title = "{quest:96781}",
					note = "In your mid 30s {npc:13085} has two more jobs; take both. Barton leads a Syndicate scouting party at {area:280}, in the east of the {zone:1416}, inside one of the houses with stealthed Syndicate around him. Pick his pocket for the report and do not kill him: he does not drop it. If you are lower than him he sees through stealth; Master of Deception helps, or Distract him, Vanish and come in from behind. {spell:921} can miss several times in a row.",
