						{ t = "accept", quest = 96786, title = "The Syndicate Sting", npc = 266847, npcName = "Anastasia Miller", minLevel = 24, qlvl = 34, map = 1417, x = 26.8, y = 64.4, f = "e", note = "{quest:96786}" },
					},
				},
				{
					title = "{quest:96786}",
					note = "Falconcrest's men make the handoff at the southern end of {area:1057}, the old wall between Arathi and {area:287}. Kill the two guarding the box and take the {item:275882}. Keep the {item:275706}: {npc:13085} wants it back with the shipment.",
					goals = {
