				{
					title = "{npc:8379}",
					note = "{npc:8395}, camped below the cliffs just east of {area:1237}, teleports you up (dismount first); a trail leads to Xylem's tower.",
					goals = {
						{ t = "turnin", quest = 8234, title = "Sealed Azure Bag", npc = 8379, npcName = "Archmage Xylem", map = 1447, x = 29.25, y = 40.21, z = 304.8, f = "e" },
						{ t = "accept", quest = 8235, title = "Encoded Fragments", npc = 8379, npcName = "Archmage Xylem", minLevel = 50, qlvl = 52, pre = { 8234 }, preTitles = { [8234] = "Sealed Azure Bag" }, map = 1447, x = 29.25, y = 40.21, z = 304.8, f = "e" },
					},
				},
				{
					title = "{quest:8235}",
					note = "The Forest Oozes (level 52-53, {spell:6907} up close) drop a fragment four times in five: the biggest group, seven of them, is in the {area:2497} hills of north-eastern {zone:1447}, four more south-east of {area:1237}. Pick their pockets before the kill for an extra fragment or two. Killing the Mistwing Ravagers and hippogryphs that share their spots makes more oozes appear.",
					goals = {
						{ t = "collect", quest = 8235, title = "Encoded Fragments", item = 20023, itemName = "Encoded Fragment", count = 10, oi = 1, map = 1447, x = 36.16, y = 67.86, f = "e", spotsPacked = "37.5,69.6,,148,2;43.1,70.5,,148,2;69.5,27.9,,176,6;75.7,27.5,,148,2;80.4,24.5,,148,1;74.7,12.7,,148,1", spread = true, lvl = 53, note = "{item:20023}: {npc:8766}", from = "Forest Ooze", fromKind = "npc", fromId = 8766, fromNpcs = { { npc = 8766, npcName = "Forest Ooze" } } },
					},
				},
				{
					title = "Back to Xylem",
					goals = {
						{ t = "turnin", quest = 8235, title = "Encoded Fragments", npc = 8379, npcName = "Archmage Xylem", map = 1447, x = 29.25, y = 40.21, z = 304.8, f = "e" },
						{ t = "accept", quest = 8236, title = "The Azure Key", npc = 8379, npcName = "Archmage Xylem", minLevel = 50, qlvl = 52, pre = { 8235 }, preTitles = { [8235] = "Encoded Fragments" }, map = 1447, x = 29.25, y = 40.21, z = 304.8, f = "e" },
					},
				},
				{
					title = "Morphaz in the {area:1417}",
					note = "Morphaz, a level 52 elite green drake, lives deep in the {area:1417}: a group of five, level 50-54. The temple stands in the {area:74}; climb into the sunken building, swim down through it and follow the passage to the portal. Horde: fly to {area:75}; Alliance: fly to {area:1438} and ride on. He is not there when you arrive: first kill the six troll guardians (elites of 50-52) on the platforms around the upper ring, which opens the way down (the left-hand ramp from the entrance) to {npc:5710} in the Pit of Sacrifice. Jammal'an's death brings out two drakes, Weaver and Dreamscythe; when both are dead, Morphaz and Hazzas appear together and fight as a pair. Their {spell:12533} is nature damage: nature protection potions help; poisons and {spell:2094} do not work on them. The key always drops. Hunters, Priests and Mages of 50 need Morphaz too: one clear serves them all.",
					goals = {
						{ t = "collect", quest = 8236, title = "The Azure Key", item = 20022, itemName = "Azure Key", count = 1, oi = 1, map = 1435, x = 69.9, y = 53.6, f = "e", note = "{item:20022}: Morphaz, inside the temple", group = { kind = "elite", rank = 1 } },
					},
				},
				{
					title = "Lord Ravenholdt",
					note = "Look at the reward window before you hand in: Classic offered the {item:19982}, the {item:19984} or the {item:20255}, and Forever's notes say the choice may be gone.",
					goals = {
						{ t = "turnin", quest = 8236, title = "The Azure Key", npc = 6768, npcName = "Lord Jorach Ravenholdt", map = 1416, x = 86.02, y = 78.88, z = 204, f = "e" },
					},
				},
			},
		})
	end
	register()
end

