			names = { ["area:204"] = "Pyrewood Village", ["area:236"] = "Shadowfang Keep", ["area:796"] = "Scarlet Monastery", ["item:210963"] = "Scryer's Key", ["item:210968"] = "Reliquary Key", ["item:277246"] = "Ruby-Adorned Blade", ["npc:4293"] = "Scarlet Scryer", ["object:410369"] = "Dead Drop", ["quest:78676"] = "The Eye of Bhossca", ["spell:427592"] = "Scarlet Initiate's Uniform", ["spell:921"] = "Pick Pocket", ["zone:1420"] = "Tirisfal Glades" },
			steps = {
				{
					title = "C's dead drop",
					note = "The {object:410369} is a chest near {area:204} in southern Silverpine, just south of {area:236}. After the horn job and C's next letter, check it for the new job. The data lists a minimum of 25, but beta players report receiving the invitation at 30 after the horn job and a city visit; this is not a guaranteed mail level. If no new note is offered, continue leveling and check after C writes.",
					goals = {
						{ t = "level", level = 25 },
						{ t = "accept", quest = 78676, title = "The Eye of Bhossca", object = 410369, objName = "Dead Drop", minLevel = 25, qlvl = 35, map = 1421, x = 47.1, y = 70.95, z = 31.8, f = "e" },
					},
				},
				{
					title = "The {area:796}",
					note = "The monastery stands in the far north-east of {zone:1420}. Go in alone, out of any group. Before entering, take the {spell:427592} from the Supply Locker in the stables behind the monastery and wear it; stealth and suspicious actions remove it, so put it back on after each wing change. In the Graveyard, in the Chamber of Atonement (the first big room), {spell:921} a {npc:4293} or Scarlet Crier for the {item:210963}. In the Library, open the Personal Letterbox in the Athenaeum with it and read the Confidential Message. It sends you back to sit on both benches between the two statues in the Graveyard. Watch for the mechanism's messages, then take the {item:210968} from the stone coffer: an elite stands by the coffer with a patrol behind it, but from beside the northern mausoleum you can turn the camera until the box shows and click it through the wall (an interact key works too). An elite ghost walks near the mausoleum; the broken piece at its edge keeps you out of its path. Then return to the Library for the locked reliquary and the eye. Avoid fighting through the instance.",
					goals = {
						{ t = "goto", text = "{area:796}", area = 796, map = 1420, x = 82.6, y = 33.8 },
						{ t = "note", text = "Solo route: Graveyard key, Library letter, Graveyard benches and coffer, then Library reliquary for the eye. Read the letter before the bench puzzle; check the disguise each time you change wings." },
					},
				},
				{
					title = "Back to the dead drop",
					note = "Place the eye in the {object:410369} near Pyrewood. Check a capital mailbox for C's payment letter on your next planned city visit, then return here for the reward quest. The payment may not be available immediately; do not repeat the infiltration just because the reward has not appeared.",
					goals = {
						{ t = "turnin", quest = 78676, title = "The Eye of Bhossca", object = 410369, objName = "Dead Drop", map = 1421, x = 47.1, y = 70.95, z = 31.8, f = "e" },
						{ t = "accept", quest = 78699, title = "The Eye of Bhossca", object = 410369, objName = "Dead Drop", minLevel = 25, qlvl = 35, map = 1421, x = 47.1, y = 70.95, z = 31.8, f = "e" },
						{ t = "turnin", quest = 78699, title = "The Eye of Bhossca", object = 410369, objName = "Dead Drop", map = 1421, x = 47.1, y = 70.95, z = 31.8, f = "e", note = "{item:277246}", rewards = { items = { { item = 277246, itemName = "Ruby-Adorned Blade" } } } },
					},
				},
			},
		})
	end
	register()
end

