						{ t = "collect", quest = 7583, title = "Suppression", item = 18605, itemName = "Imprisoned Doomguard", count = 1, oi = 1, map = 1419, x = 34.55, y = 63.73, f = "e", spotsPacked = "34.7,63.7,,54,2;39,67.9,,54,2;40.1,63.3,,54,1;44.2,74,,54,4;41.6,78.1,,57,3;58.2,55.3,,54,2,1", spread = true, note = "{item:18605}, click it", from = "Imprisoned Doomguard", fromKind = "object", fromId = 179644 },
					},
