			names = { ["area:2159"] = "Onyxia's Lair", ["area:2577"] = "Dire Maul", ["area:511"] = "Wyrmbog", ["item:18249"] = "Crescent Key", ["item:18348"] = "Quel'Serrar", ["item:18401"] = "Nostro's Compendium of Dragon Slaying", ["item:18488"] = "Heated Ancient Blade", ["item:18489"] = "Unfired Ancient Blade", ["item:18492"] = "Treated Ancient Blade", ["item:18513"] = "A Dull and Flat Elven Blade", ["npc:10184"] = "Onyxia", ["npc:11496"] = "Immol'thar", ["npc:11501"] = "King Gordok", ["npc:14368"] = "Lorekeeper Lydros", ["object:179562"] = "Ancient Heated Blade", ["quest:7509"] = "The Forging of Quel'Serrar", ["zone:1444"] = "Feralas", ["zone:1445"] = "Dustwallow Marsh" },
			steps = {
				{
					title = "{item:18401}",
					note = "The book is a rare random drop from the bosses of all three {area:2577} wings (Alzzin, Hydrospawn and the rest of the East, Tendris, Illyanna, Kalendris, {npc:11496} and the West, {npc:11501} and the North's guards) and very rarely from the tribute chest; it can be traded, so the auction house may have one. {area:2577} is a five-player dungeon in the ruins of central {zone:1444}: needs a group of five. Right-click the book to start the quest; it stays in your bags.",
					goals = {
						{ t = "accept", quest = 7507, title = "Foror's Compendium", item = 18401, itemName = "Nostro's Compendium of Dragon Slaying", minLevel = 60, qlvl = 60, note = "from {item:18401}", group = { kind = "group", size = 5 } },
					},
				},
				{
					title = "{npc:14368}",
					note = "{npc:14368} stands in the Athenaeum, the library at the far end of Dire Maul West, past the Court of the Highborne and the Prison of Immol'thar. The West door needs the {item:18249}, which Pusillin drops in Dire Maul East (he runs; chase him), or a rogue to pick it. Clearing to the library needs your group of five. He takes the book, hands you {item:18513} to give straight back, then the {item:18489}. Keep that blade: lose it, and you must abandon the quest and take it again.",
					goals = {
						{ t = "turnin", quest = 7507, title = "Foror's Compendium", npc = 14368, npcName = "Lorekeeper Lydros", map = 1444, x = 59.2, y = 45.1, f = "e", note = "{npc:14368}, in the Athenaeum", group = { kind = "group", size = 5 } },
						{ t = "accept", quest = 7508, title = "The Forging of Quel'Serrar", npc = 14368, npcName = "Lorekeeper Lydros", minLevel = 60, qlvl = 60, pre = { 7507 }, preTitles = { [7507] = "Foror's Compendium" }, map = 1444, x = 59.2, y = 45.1, f = "e", group = { kind = "dungeon", map = 429, name = "Dire Maul" } },
						{ t = "turnin", quest = 7508, title = "The Forging of Quel'Serrar", npc = 14368, npcName = "Lorekeeper Lydros", map = 1444, x = 59.2, y = 45.1, f = "e", note = "{npc:14368}: hand back the Dull and Flat Elven Blade", group = { kind = "dungeon", map = 429, name = "Dire Maul" } },
						{ t = "accept", quest = 7509, title = "The Forging of Quel'Serrar", npc = 14368, npcName = "Lorekeeper Lydros", minLevel = 60, qlvl = 60, pre = { 7508 }, preTitles = { [7508] = "The Forging of Quel'Serrar" }, map = 1444, x = 59.2, y = 45.1, f = "e", group = { kind = "raid", map = 249, name = "Onyxia's Lair" } },
					},
				},
				{
					title = "{npc:10184}'s breath",
					note = "{npc:10184} is the 40-player raid boss of {area:2159}, a cave in the {area:511} of southern {zone:1445}; she returns once a week. Tell the raid first. Late in the fight (around 10-15% health, when she has landed again) use the {item:18489} to plant it in the path of her fire breath, usually by the main tank's feet. When her breath has heated it, click the {object:179562} to take the {item:18488}: from then you have 20 minutes. Her breath can kill you while you plant or pick up the blade; if you die and nobody brings you back before she dies, wait for next week. Planted in the wrong place? Abandon the quest, take it again from Lydros for a new blade.",
					goals = {
						{ t = "use", item = 18489, itemName = "Unfired Ancient Blade", map = 1445, x = 52.1, y = 75.8, f = "e", note = "{item:18489}: plant it in her breath", group = { kind = "group", size = 40 } },
						{ t = "collect", item = 18488, itemName = "Heated Ancient Blade", map = 1445, x = 52.1, y = 75.8, f = "e", note = "click the heated blade on the ground" },
					},
				},
				{
					title = "{npc:10184}'s corpse",
					note = "Kill {npc:10184}, then target her corpse and use the {item:18488} on it before the 20 minutes run out. It becomes the {item:18492}, with no time limit.",
					goals = {
						{ t = "kill", target = "Onyxia", npc = 10184, map = 1445, x = 52.1, y = 75.8, f = "e", group = { kind = "group", size = 40 } },
						{ t = "use", quest = 7509, title = "The Forging of Quel'Serrar", item = 18488, itemName = "Heated Ancient Blade", oi = 1, map = 1445, x = 52.1, y = 75.8, f = "e", note = "{item:18488}, on her corpse", group = { kind = "raid", map = 249, name = "Onyxia's Lair" } },
						{ t = "collect", quest = 7509, title = "The Forging of Quel'Serrar", item = 18492, itemName = "Treated Ancient Blade", count = 1, oi = 1, map = 1445, x = 52.1, y = 75.8, f = "e", group = { kind = "raid", map = 249, name = "Onyxia's Lair" } },
					},
				},
				{
					title = "{quest:7509}",
					note = "Back to {npc:14368} in the Athenaeum of Dire Maul West: through the West door with the {item:18249} again, and a group to reach the library.",
					goals = {
						{ t = "turnin", quest = 7509, title = "The Forging of Quel'Serrar", npc = 14368, npcName = "Lorekeeper Lydros", map = 1444, x = 59.2, y = 45.1, f = "e", note = "{npc:14368}: {item:18348}", rewards = { items = { { item = 18348, itemName = "Quel'Serrar" } } }, group = { kind = "group", size = 5 } },
