			reward = { { spell = 23161, spellName = "Summon Dreadsteed" } },
			why = "Your epic mount at 60, summoned anywhere: no epic horse to buy and no 1,000g Journeyman Riding needed.",
			zone = 1428,
			zoneName = "Burning Steppes",
			author = "Polestar",
			version = 1,
			group = true,
			names = { ["area:1584"] = "Blackrock Depths", ["area:1763"] = "Jaedenar", ["area:1770"] = "Shadow Hold", ["area:1997"] = "Bloodvenom Post", ["area:2057"] = "Scholomance", ["area:2242"] = "Hidden Grove", ["area:2250"] = "Owl Wing Thicket", ["area:2298"] = "Caer Darrow", ["area:254"] = "Blackrock Mountain", ["area:255"] = "Altar of Storms", ["area:2577"] = "Dire Maul", ["item:11370"] = "Dark Iron Ore", ["item:12359"] = "Thorium Bar", ["item:12360"] = "Arcanite Bar", ["item:12363"] = "Arcane Crystal", ["item:13704"] = "Skeleton Key", ["item:14344"] = "Large Brilliant Shard", ["item:15416"] = "Black Dragonscale", ["item:18249"] = "Crescent Key", ["item:18590"] = "Raging Beast's Blood", ["item:18591"] = "Case of Blood", ["item:18629"] = "Black Lodestone", ["item:18663"] = "J'eevee's Jar", ["item:18670"] = "Xorothian Glyphs", ["item:18687"] = "Xorothian Stardust", ["item:18688"] = "Imp in a Jar", ["item:18802"] = "Shadowy Potion", ["item:6265"] = "Soul Shard", ["item:8845"] = "Ghost Mushroom", ["item:8925"] = "Crystal Vial", ["item:9264"] = "Elixir of Shadow Power", ["npc:10508"] = "Ras Frostwhisper", ["npc:11496"] = "Immol'thar", ["npc:14436"] = "Mor'zul Bloodbringer", ["npc:14437"] = "Gorzeeki Wildeyes", ["npc:14483"] = "Dread Guard", ["npc:14500"] = "J'eevee", ["npc:14502"] = "Xorothian Dreadsteed", ["npc:14504"] = "Dreadsteed Spirit", ["npc:14506"] = "Lord Hel'nurath", ["npc:14522"] = "Ur'dan", ["npc:14523"] = "Ulathek", ["npc:5520"] = "Spackle Thornberry", ["npc:5753"] = "Martha Strain", ["npc:5815"] = "Kurgul", ["npc:6382"] = "Jubahl Corpseseeker", ["npc:7043"] = "Flamescale Wyrmkin", ["npc:9516"] = "Lord Banehollow", ["object:165658"] = "Dark Iron Deposit", ["object:172960"] = "Cleft of Shadow", ["object:2164"] = "Slaughtered Lamb", ["object:36082"] = "Magic Quarter", ["quest:7562"] = "Mor'zul Bloodbringer", ["quest:7564"] = "Wildeyes", ["quest:7623"] = "Lord Banehollow", ["quest:7624"] = "Ulathek the Traitor", ["quest:7625"] = "Xorothian Stardust", ["quest:7626"] = "Bell of Dethmoora", ["quest:7627"] = "Wheel of the Black March", ["quest:7628"] = "Doomsday Candle", ["quest:7629"] = "Imp Delivery", ["quest:7630"] = "Arcanite", ["quest:7631"] = "Dreadsteed of Xoroth", ["skill:171"] = "Alchemy", ["skill:186"] = "Mining", ["skill:333"] = "Enchanting", ["skill:393"] = "Skinning", ["spell:23161"] = "Summon Dreadsteed", ["spell:23179"] = "Taint of Shadow", ["zone:1422"] = "Western Plaguelands", ["zone:1428"] = "Burning Steppes", ["zone:1444"] = "Feralas", ["zone:1448"] = "Felwood", ["zone:1452"] = "Winterspring", ["zone:1453"] = "Stormwind", ["zone:1454"] = "Orgrimmar", ["zone:1455"] = "Ironforge", ["zone:1458"] = "Undercity" },
			written = { ["Back to {npc:14436}: he gives you the {item:18591} for {npc:14437} beside him. Then {npc:14436} asks for the bell, the wheel and the candle, and {npc:14437} sends you to {quest:7623} in {area:1763}: buy three Shadowy Potions from him for that trip (6 gold each: one to walk in, one after {npc:14523}, and a spare in case one runs out) and bring 150 gold for the stardust."] = "Back to Mor'zul: he gives you the Case of Blood for Gorzeeki beside him. Then Mor'zul asks for the bell, the wheel and the candle, and Gorzeeki sends you to Lord Banehollow in Jaedenar: buy three Shadowy Potions from him for that trip (6 gold each: one to walk in, one after Ulathek, and a spare in case one runs out) and bring 150 gold for the stardust.", ["Back to {npc:14437} with the stardust; with the {quest:7630} also done he gives you the {item:18688} for the {area:2057}. Put a group of five together now: a party, not a raid group."] = "Back to Gorzeeki with the stardust; with the Arcanite also done he gives you the Imp in a Jar for the Scholomance. Put a group of five together now: a party, not a raid group.", ["Back to {npc:14437}, then {npc:14436} hands you his instructions. Buy {item:18663} (150 gold), the {item:18629} (50) and the {item:18670} (50) from {npc:14437}; a warlock friend who owns them can bring theirs instead. Every other warlock who will recharge the nodes needs a Lodestone of their own. Carry 15 or more Soul Shards."] = "Back to Gorzeeki, then Mor'zul hands you his instructions. Buy J'eevee's Jar (150 gold), the Black Lodestone (50) and the Xorothian Glyphs (50) from Gorzeeki; a warlock friend who owns them can bring theirs instead. Every other warlock who will recharge the nodes needs a Lodestone of their own. Carry 15 or more Soul Shards.", ["Hand the three pieces to {npc:14437}. He then wants 3 Arcanite Bars for the {item:18629}: alchemists transmute them (an {item:12363} and a {item:12359} each, on a long cooldown); everyone else buys them."] = "Hand the three pieces to Gorzeeki. He then wants 3 Arcanite Bars for the Black Lodestone: alchemists transmute them (an Arcane Crystal and a Thorium Bar each, on a long cooldown); everyone else buys them.", ["{item:18802}, from {npc:14437}"] = "Shadowy Potion, from Gorzeeki", ["{npc:14437} wants 10 Elixirs of Shadow Power ({skill:171}: 3 Ghost Mushrooms and a {item:8925} each), 6 Large Brilliant Shards ({skill:333}: disenchant level 51+ blue items), 25 {item:11370} ({skill:186} 230: the Dark Iron Deposits of the {zone:1428} and {area:1584}) and 35 Black Dragonscales ({skill:393}: the black dragonkin of the {zone:1428}, a few percent a kill, best from the {npc:7043}). Make or gather what your professions allow and buy the rest at the Auction House; it can take a while to find 35 scales."] = "Gorzeeki wants 10 Elixirs of Shadow Power (Alchemy: 3 Ghost Mushrooms and a Crystal Vial each), 6 Large Brilliant Shards (Enchanting: disenchant level 51+ blue items), 25 Dark Iron Ore (Mining 230: the Dark Iron Deposits of the Burning Steppes and Blackrock Depths) and 35 Black Dragonscales (Skinning: the black dragonkin of the Burning Steppes, a few percent a kill, best from the Flamescale Wyrmkin). Make or gather what your professions allow and buy the rest at the Auction House; it can take a while to find 35 scales.", ["{quest:7562} and his goblin {npc:14437} camp on the hill across the road from the {area:255}, in the far north-west of the {zone:1428}, west of {area:254}. The chain is long: about 420 gold in {npc:14437}'s and {npc:14522}'s goods, a pile of crafted materials, the {area:2057} and {area:2577}. Start buying or gathering the materials of the next steps now."] = "Mor'zul Bloodbringer and his goblin Gorzeeki Wildeyes camp on the hill across the road from the Altar of Storms, in the far north-west of the Burning Steppes, west of Blackrock Mountain. The chain is long: about 420 gold in Gorzeeki's and Ur'dan's goods, a pile of crafted materials, the Scholomance and Dire Maul. Start buying or gathering the materials of the next steps now." },
			steps = {
