				{
					title = "{quest:7623}",
					note = "{area:1763} lies just south of {area:1997} in western {zone:1448}, west of the road; of its two caves, {area:1770} is the northern one, further up the hill. Drink a {item:18802} at its mouth: for 20 minutes the Shadow Council there treat you as one of their own ({spell:23179}). The oozes in the red pool and the succubus Rakaiah beyond them still attack: hug the wall past them. Go down past the second, red pool, up the ramp and across two bridges to {quest:7623}, a great winged dreadlord at the back. He talks to you only while the potion lasts.",
					goals = {
						{ t = "goto", text = "{area:1770}", area = 1770, map = 1448, x = 35.4, y = 58.6, f = "e" },
						{ t = "turnin", quest = 7623, title = "Lord Banehollow", npc = 9516, npcName = "Lord Banehollow", map = 1448, x = 35.9, y = 44.4, z = 272.6, f = "e" },
						{ t = "accept", quest = 7624, title = "Ulathek the Traitor", npc = 9516, npcName = "Lord Banehollow", minLevel = 60, qlvl = 58, pre = { 7623 }, preTitles = { [7623] = "Lord Banehollow" }, map = 1448, x = 35.93, y = 44.42, z = 272.6, f = "e" },
					},
				},
				{
					title = "{quest:7624}",
					note = "{npc:14523} waits in a small side room up a bridge you passed on the way down. Speak to him and he and four guards attack (all level 57, none elite): let your voidwalker hold the guards and burn {npc:14523}, sacrificing it if you must. Or click off your {spell:23179} aura to start the fight, kill {npc:14523}, then drink another potion: the guards stop at once. Take his heart back to {npc:9516} with a potion active.",
					goals = {
						{ t = "kill", target = "Ulathek", npc = 14523, map = 1448, x = 40.76, y = 48.42, z = 268.8, f = "e", optional = true },
						{ t = "collect", quest = 7624, title = "Ulathek the Traitor", item = 18719, itemName = "The Traitor's Heart", count = 1, oi = 1, map = 1448, x = 40.76, y = 48.42, f = "e", from = "Ulathek", fromKind = "npc", fromId = 14523, fromNpcs = { { npc = 14523, npcName = "Ulathek" } } },
						{ t = "turnin", quest = 7624, title = "Ulathek the Traitor", npc = 9516, npcName = "Lord Banehollow", map = 1448, x = 35.9, y = 44.4, z = 272.6, f = "e" },
