					title = "{item:18687}",
					note = "{npc:14522}, beside {quest:7623}, sells the {item:18687} for 150 gold. He deals with you only while a {item:18802} is active.",
					goals = {
						{ t = "buy", npc = 14522, npcName = "Ur'dan", item = 18687, itemName = "Xorothian Stardust", map = 1448, x = 36.18, y = 44.46, z = 273.1, f = "e", note = "{item:18687}, from {npc:14522}" },
					},
				},
				{
					title = "{quest:7629}",
					note = "Back to {npc:14437} with the stardust; with the {quest:7630} also done he gives you the {item:18688} for the {area:2057}. Put a group of five together now: a party, not a raid group.",
					goals = {
						{ t = "buy", npc = 14522, npcName = "Ur'dan", item = 18687, itemName = "Xorothian Stardust", map = 1448, x = 36.18, y = 44.46, z = 273.1, f = "e", note = "{quest:7625}, from {npc:14522}" },
						{ t = "turnin", quest = 7625, title = "Xorothian Stardust", npc = 14437, npcName = "Gorzeeki Wildeyes", map = 1428, x = 12.44, y = 31.63, z = 200.6, f = "e" },
						{ t = "accept", quest = 7629, title = "Imp Delivery", npc = 14437, npcName = "Gorzeeki Wildeyes", minLevel = 60, qlvl = 60, pre = { 7625 }, preTitles = { [7625] = "Xorothian Stardust" }, map = 1428, x = 12.44, y = 31.63, z = 200.6, f = "e" },
					},
				},
				{
					title = "The {area:2057}",
					note = "The {area:2057} (level 58-60, a group of five) lies under {area:2298}, the island town in the south-east of the {zone:1422}: someone needs the {item:13704} or a rogue to open the door. Fight down to {npc:10508}'s room and use the {item:18688} at the alchemy lab tables to the right: {npc:14500} makes the parchment. You need not kill Ras, but it only counts at this lab and only in a party.",
					goals = {
						{ t = "complete", quest = 7629, title = "Imp Delivery", map = 1422, x = 69.7, y = 73.2, f = "e", note = "Use the {item:18688} at the alchemy lab inside", group = { kind = "group", size = 5 }, objs = { { text = "J'eevee", count = 1 } }, startItem = 18688, startItemName = "Imp in a Jar" },
					},
				},
				{
					title = "{quest:7631}",
					note = "Back to {npc:14437}, then {npc:14436} hands you his instructions. Buy {item:18663} (150 gold), the {item:18629} (50) and the {item:18670} (50) from {npc:14437}; a warlock friend who owns them can bring theirs instead. Every other warlock who will recharge the nodes needs a Lodestone of their own. Carry 15 or more Soul Shards.",
					goals = {
						{ t = "turnin", quest = 7629, title = "Imp Delivery", npc = 14437, npcName = "Gorzeeki Wildeyes", map = 1428, x = 12.44, y = 31.63, z = 200.6, f = "e" },
						{ t = "accept", quest = 7631, title = "Dreadsteed of Xoroth", npc = 14436, npcName = "Mor'zul Bloodbringer", minLevel = 60, qlvl = 60, preAll = { 7629, 7630 }, preTitles = { [7629] = "Imp Delivery", [7630] = "Arcanite" }, map = 1428, x = 12.69, y = 31.64, z = 201, f = "e" },
						{ t = "buy", npc = 14437, npcName = "Gorzeeki Wildeyes", item = 18663, itemName = "J'eevee's Jar", map = 1428, x = 12.44, y = 31.63, z = 200.6, f = "e", note = "{item:18663}, 150 gold" },
						{ t = "buy", npc = 14437, npcName = "Gorzeeki Wildeyes", item = 18629, itemName = "Black Lodestone", map = 1428, x = 12.44, y = 31.63, z = 200.6, f = "e", note = "{item:18629}, 50 gold" },
						{ t = "buy", npc = 14437, npcName = "Gorzeeki Wildeyes", item = 18670, itemName = "Xorothian Glyphs", map = 1428, x = 12.44, y = 31.63, z = 200.6, f = "e", note = "{item:18670}, 50 gold" },
					},
				},
				{
					title = "Into Dire Maul West",
					note = "{area:2577} stands in the ruins of central {zone:1444}: from the gate at the foot of the ruins, walk up through the outer courtyards to the west wing's door at the north end. That door and an inner door need the {item:18249} (it drops from Pusillin in Dire Maul East) or a rogue with 300 Lockpicking. Bring a party of five. Lower {npc:11496}'s shield by killing the guardians of the five pylons (two stand in his own room), then kill {npc:11496}: his dais is the summoning circle. Rest and rebuff before you start.",
					goals = {
						{ t = "kill", target = "Immol'thar", npc = 11496, map = 1444, x = 60.3, y = 30.2, f = "e", note = "{npc:11496}, inside the west wing", group = { kind = "group", size = 5 } },
					},
				},
				{
					title = "The ritual",
					note = "Stand on the dais and use {item:18663}: {npc:14500} sets out the Bell, the Wheel and the Candle. The Bell heals warlocks, the Wheel shields the party, the Candle burns the imps: ignore the imps and kill the Dread Guards (elite felguards, about ten, sometimes two at once); Banish or Enslave helps. Give one player each node to watch: when one sags, tilts and sounds, a warlock with a Lodestone recharges it, a 3-second cast that any hit breaks (a {item:6265} each), so keep attackers off them. If all three fail, the ritual ends and you start again; while one stands it survives even a wipe. After about six minutes nine symbols glow and a red vortex closes the circle: walk out and the remaining demons vanish at its edge. Rest, then use the {item:18670}. Kill the {npc:14502} (level 62, elite); at half health {npc:14506} joins, a hard hitter who knocks you back. Speak to the {npc:14504}: every warlock in the party who is on this quest can bind it.",
					goals = {
						{ t = "use", item = 18663, itemName = "J'eevee's Jar", map = 1444, x = 60.3, y = 30.2, f = "e", note = "{item:18663}, on {npc:11496}'s dais" },
						{ t = "use", item = 18670, itemName = "Xorothian Glyphs", map = 1444, x = 60.3, y = 30.2, f = "e", note = "{item:18670}, once the circle is complete" },
						{ t = "kill", quest = 7631, title = "Dreadsteed of Xoroth", target = "Xorothian Dreadsteed", npc = 14502, count = 1, oi = 1, map = 1444, x = 60.3, y = 30.2, f = "e", group = { kind = "group", size = 5 } },
						{ t = "turnin", quest = 7631, title = "Dreadsteed of Xoroth", npc = 14504, npcName = "Dreadsteed Spirit", map = 1444, x = 60.3, y = 30.2, f = "e", note = "{npc:14504}: {spell:23161}" },
					},
				},
			},
		})
	end
