				{
					title = "{area:2268} quests",
					note = "{area:2268}, on the east side of the {zone:1423}, is the {faction:529}'s home: {npc:11039}, {npc:11035} and {npc:243254} give its dungeon quests, 100 to 200 reputation each and about 1,700 in all. They are group quests for {area:2279} and {area:2057} (level 58-60, five players): take the ones your group will run. The Duke's chain ends at the {object:176317}, a chest of {faction:529} gear.",
					goals = {
						{ t = "level", level = 55 },
						{ t = "accept", quest = 5212, title = "The Flesh Does Not Lie", npc = 11035, npcName = "Betina Bigglezink", minLevel = 55, qlvl = 60, map = 1423, x = 71.66, y = 49.94, z = 86.8, optional = true, note = "{quest:5212}: {npc:11035}", group = { kind = "dungeon", map = 329, name = "Stratholme" } },
						{ t = "accept", quest = 5529, title = "Plagued Hatchlings", npc = 11035, npcName = "Betina Bigglezink", minLevel = 55, qlvl = 58, map = 1423, x = 71.66, y = 49.94, z = 86.8, optional = true, note = "{quest:5529}: {npc:11035}", group = { kind = "dungeon", map = 289, name = "Scholomance" } },
						{ t = "accept", quest = 5243, title = "Houses of the Holy", npc = 11036, npcName = "Leonid Barthalomew the Revered", minLevel = 55, qlvl = 60, map = 1423, x = 71.89, y = 48.29, z = 91.7, optional = true, note = "{quest:5243}: {npc:243254}", group = { kind = "dungeon", map = 329, name = "Stratholme" } },
						{ t = "accept", quest = 5251, title = "The Archivist", npc = 11039, npcName = "Duke Nicholas Zverenhoff", minLevel = 55, qlvl = 60, map = 1423, x = 71.63, y = 50.09, z = 86.3, optional = true, note = "{quest:5251}: {npc:11039}", group = { kind = "dungeon", map = 329, name = "Stratholme" } },
					},
				},
				{
					title = "{area:2279}",
					note = "{area:2279} is a group of five at the north end of the {zone:1423}. Its Scourge give 5 reputation a kill up to the last point of Honored, and its Scourge bosses 25 until Exalted ({npc:10440} 50), each with a {item:12843}. The Black Guard Sentries by the Baron give 5 until Exalted. The Scourge side, through the service entrance, pays far more than the Scarlet side.",
					goals = {
						{ t = "goto", text = "{area:2279}", area = 2279, map = 1423, x = 26.5, y = 10.4 },
						{ t = "collect", quest = 5212, title = "The Flesh Does Not Lie", item = 13174, itemName = "Plagued Flesh Sample", count = 10, oi = 1, map = 1423, x = 26.5, y = 10.4, note = "Plagued Flesh Samples: the Scourge inside", group = { kind = "group", size = 5 } },
						{ t = "collect", quest = 5243, title = "Houses of the Holy", item = 13180, itemName = "Stratholme Holy Water", count = 5, oi = 1, map = 1423, x = 26.5, y = 10.4, note = "{item:13180}: the supply crates", group = { kind = "group", size = 5 } },
						{ t = "kill", quest = 5251, title = "The Archivist", target = "Archivist Galford", npc = 10811, count = 1, oi = 1, map = 1423, x = 26.5, y = 10.4, note = "{npc:10811}, Scarlet side", group = { kind = "group", size = 5 } },
					},
				},
				{
					title = "{area:2057}",
					note = "{area:2057} lies under {area:2298}, the island town in the south-east of the {zone:1422}; your side's {area:2057} quests give the {item:13704} that opens it. It is the best {faction:529} run: its mobs give 5 up to the last point of Honored, and its thirteen bosses about 375 reputation a full clear plus ten or so {quest:5508} (about 250 more). {npc:10508} and {npc:1853} give 50 each.",
					goals = {
						{ t = "goto", text = "{area:2057}", area = 2057, map = 1422, x = 69.7, y = 73.2, f = "e" },
						{ t = "kill", quest = 5529, title = "Plagued Hatchlings", target = "Plagued Hatchling", npc = 10678, count = 20, oi = 1, map = 1422, x = 69.7, y = 73.2, f = "e", note = "{quest:5529}, in the hatchery", group = { kind = "group", size = 5 } },
					},
				},
				{
					title = "Back at {area:2268}",
