				{
					title = "{quest:1036}",
					note = "\"Pretty Boy\" Duncan, a Bloodsail pirate, stands on the beach north of {area:35}. {area:35} players kill him for a quest: if he is not there, wait for him. He has a quest for you from level 55, while {area:35} is below Neutral; it is done once you are Friendly with the Bloodsail and Hated with {area:35}.",
					goals = {
						{ t = "accept", quest = 1036, title = "Avast Ye, Scallywag", npc = 2545, npcName = "\"Pretty Boy\" Duncan", minLevel = 55, qlvl = 60, closedBy = { 4621 }, preTitles = { [4621] = "Avast Ye, Admiral!" }, map = 1434, x = 27.39, y = 69.42, z = 1.2, f = "e" },
						{ t = "turnin", quest = 1036, title = "Avast Ye, Scallywag", npc = 2546, npcName = "Fleet Master Firallon", map = 1434, x = 30.58, y = 90.63, z = 7.5, f = "e", note = "{npc:2546}, on the {area:1757}: 25" },
						{ t = "accept", quest = 4621, title = "Avast Ye, Admiral!", npc = 2546, npcName = "Fleet Master Firallon", minLevel = 55, qlvl = 60, map = 1434, x = 30.58, y = 90.63, z = 7.5, f = "e" },
					},
				},
				{
					title = "{quest:4621}",
					note = "{npc:2496} and {npc:2487} stand on the top floor of the {area:35} inn, out on the balcony. Both are level 60 and Bruisers come to their aid: clear the stairs first and pull them one at a time. They come back, so a friend can kill them too.",
					goals = {
						{ t = "kill", quest = 4621, title = "Avast Ye, Admiral!", target = "Baron Revilgaz", npc = 2496, count = 1, oi = 1, map = 1434, x = 27.23, y = 76.87, z = 28.9, f = "e" },
						{ t = "kill", quest = 4621, title = "Avast Ye, Admiral!", target = "Fleet Master Seahorn", npc = 2487, count = 1, oi = 2, map = 1434, x = 27.17, y = 77.01, z = 28.8, f = "e" },
					},
				},
				{
					title = "The {item:10030}",
					note = "Back to Firallon for the {item:12185} (in Classic its use calls a parrot to your shoulder): 200 more Bloodsail and 1,000 less {area:35}. Bruisers pay 25 only up to the end of Honored and Jazzrik, a lone goblin in the {zone:1418}, 5 up to the end of Revered; no quest is left, so Exalted cannot be reached.",
					goals = {
						{ t = "turnin", quest = 4621, title = "Avast Ye, Admiral!", npc = 2546, npcName = "Fleet Master Firallon", map = 1434, x = 30.58, y = 90.63, z = 7.5, f = "e", note = "{npc:2546}: {item:12185}", rewards = { items = { { item = 12185, itemName = "Bloodsail Admiral's Hat" } } } },
					},
				},
				{
					title = "The way back",
					note = "Every goblin town is now Hated. Forever's quest data takes the town reputation off the four goblin amends quests outside {area:392}, {area:35}, {area:976} and {area:2255}, so the climb back is the Cartel's own: {npc:14637} in {zone:1444} serves everyone, and his Zapped Giants quests pay 25 to every town at once; Bloodsail pirates give {area:35} 5 each up to the end of Neutral (and cost Bloodsail 25); Southsea pirates and the Venture Co. in Stranglethorn give the towns 5 each. The Steamwheedle Cartel guide has the details. Expect it to take longer than the war did.",
					goals = {
						{ t = "talk", npc = 14637, npcName = "Zorbin Fandazzle", map = 1444, x = 44.81, y = 43.42, z = 1.5, f = "e", optional = true, note = "{npc:14637}: Zapped Giants, open to the Hated" },
					},
				},
			},
		})
	end
	register()
end

