						{ t = "turnin", quest = 8236, title = "The Azure Key", npc = 6768, npcName = "Lord Jorach Ravenholdt", map = 1416, x = 86.02, y = 78.88, z = 204, f = "e", optional = true, note = "{npc:6768}: 150" },
					},
				},
				{
					title = "Heavy Junkboxes to Exalted",
					note = "From the top of Honored to Exalted is 21,001 reputation, and {quest:8249} is the only way: {npc:6707} pays 50 and a {item:20086} for every five Heavy Junkboxes (Classic Era paid 75), 421 turn-ins and 2,105 boxes. Boxes count at any standing, so take the cheap kills to their cap first. Any class can hand them in. Rogues get them by picking the pockets of humanoids around level 50 and up: Lower {area:1583} and {area:1584} are the classic spots, pick every pocket, reset and go again. The boxes do not bind, so everyone else buys them from rogues or at the auction house. Hand them in unopened; an opened box you empty vanishes, so leave one item in it.",
					goals = {
						{ t = "level", level = 50 },
						{ t = "collect", item = 16885, itemName = "Heavy Junkbox", count = 5, map = 1427, x = 32.1, y = 94.7, f = "e", optional = true, note = "{item:16885}: pickpocket level 50+ humanoids, {area:1445}" },
						{ t = "accept", quest = 8249, title = "Junkboxes Needed", npc = 6707, npcName = "Fahrad", minLevel = 50, qlvl = 60, map = 1416, x = 84.45, y = 80.32, z = 203.9, f = "e", optional = true },
						{ t = "turnin", quest = 8249, title = "Junkboxes Needed", npc = 6707, npcName = "Fahrad", map = 1416, x = 84.45, y = 80.32, z = 203.9, f = "e", optional = true, note = "{npc:6707}: 50 per five boxes" },
						{ t = "rep", faction = 349, factionName = "Ravenholdt", standing = 8 },
