			names = { ["area:1443"] = "The Slag Pit", ["area:1445"] = "Blackrock Mountain", ["area:1446"] = "Thorium Point", ["area:1584"] = "Blackrock Depths", ["area:2717"] = "Molten Core", ["area:976"] = "Gadgetzan", ["item:10999"] = "Ironfel", ["item:11000"] = "Shadowforge Key", ["item:11370"] = "Dark Iron Ore", ["item:11382"] = "Blood of the Mountain", ["item:12359"] = "Thorium Bar", ["item:16979"] = "Flarecore Gloves", ["item:16980"] = "Flarecore Mantle", ["item:16982"] = "Corehound Boots", ["item:16983"] = "Molten Helm", ["item:16984"] = "Black Dragonscale Boots", ["item:16988"] = "Fiery Chain Shoulders", ["item:16989"] = "Fiery Chain Girdle", ["item:17010"] = "Fiery Core", ["item:17011"] = "Lava Core", ["item:17012"] = "Core Leather", ["item:17013"] = "Dark Iron Leggings", ["item:17014"] = "Dark Iron Bracers", ["item:17015"] = "Dark Iron Reaver", ["item:17016"] = "Dark Iron Destroyer", ["item:17182"] = "Sulfuras, Hand of Ragnaros", ["item:17203"] = "Sulfuron Ingot", ["item:17204"] = "Eye of Sulfuras", ["item:18592"] = "Plans: Sulfuron Hammer", ["item:18628"] = "Thorium Brotherhood Contract", ["item:18922"] = "Secret Plans: Fiery Flux", ["item:18942"] = "Fiery Flux", ["item:18944"] = "Incendosaur Scale", ["item:18945"] = "Dark Iron Residue", ["item:18946"] = "Head of Overseer Maltorius", ["item:18950"] = "Chambermaid Pillaclencher's Pillow", ["item:18959"] = "Smithing Tuyere", ["item:18960"] = "Lookout's Spyglass", ["item:19148"] = "Dark Iron Helm", ["item:19149"] = "Lava Belt", ["item:19156"] = "Flarecore Robe", ["item:19157"] = "Chromatic Gauntlets", ["item:19162"] = "Corehound Belt", ["item:19163"] = "Molten Belt", ["item:19164"] = "Dark Iron Gauntlets", ["item:19165"] = "Flarecore Leggings", ["item:19166"] = "Black Amnesty", ["item:19170"] = "Ebon Hand", ["item:20039"] = "Dark Iron Boots", ["item:273572"] = "Enchant Weapon - Strength", ["item:273576"] = "Enchant Weapon - Mighty Spirit", ["item:273577"] = "Enchant Weapon - Mighty Intellect", ["item:2772"] = "Iron Ore", ["item:3356"] = "Kingsblood", ["item:3575"] = "Iron Bar", ["item:4234"] = "Heavy Leather", ["npc:11659"] = "Molten Destroyer", ["npc:11673"] = "Ancient Core Hound", ["npc:11988"] = "Golemagg the Incinerator", ["npc:12076"] = "Lava Elemental", ["npc:12100"] = "Lava Reaver", ["npc:12944"] = "Lokhtos Darkbargainer", ["npc:14567"] = "Derotain Mudsipper", ["npc:14621"] = "Overseer Maltorius", ["npc:14624"] = "Master Smith Burninate", ["npc:14628"] = "Evonice Sootsmoker", ["npc:14636"] = "Chambermaid Pillaclencher", ["npc:5840"] = "Dark Iron Steamsmith", ["npc:5846"] = "Dark Iron Taskmaster", ["npc:5854"] = "Heavy War Golem", ["npc:5858"] = "Greater Lava Spider", ["npc:8566"] = "Dark Iron Lookout", ["npc:8888"] = "Franclorn Forgewright", ["npc:9056"] = "Fineous Darkvire", ["npc:9318"] = "Incendosaur", ["object:147516"] = "Dark Iron", ["object:161460"] = "Shadowforge Lock", ["object:164689"] = "Monument of Franclorn Forgewright", ["object:165658"] = "Dark Iron Deposit", ["object:179827"] = "Wanted/Missing/Lost & Found", ["quest:7604"] = "A Binding Contract", ["quest:7652"] = "A Blue Light Bargain", ["quest:7722"] = "What the Flux?", ["quest:7737"] = "Gaining Acceptance", ["skill:186"] = "Mining", ["zone:1427"] = "Searing Gorge", ["zone:1428"] = "Burning Steppes" },
			written = { ["Carry a {item:17203} ({npc:11988}, the {area:2717}) to {npc:12944} and he offers you a contract: ask about the offer and take it. Handing in the contract with the ingot pays 200 reputation and {item:18592}, the hammer Blacksmiths later join with the {item:17204} into {item:17182}."] = "Carry a Sulfuron Ingot (Golemagg the Incinerator, the Molten Core) to Lokhtos and he offers you a contract: ask about the offer and take it. Handing in the contract with the ingot pays 200 reputation and Plans: Sulfuron Hammer, the hammer Blacksmiths later join with the Eye of Sulfuras into Sulfuras, Hand of Ragnaros.", ["Friendly to Honored is 6,000 reputation. While you are Friendly Burninate takes {quest:7737} instead: 25 reputation for 4 {item:18945}, 240 turn-ins and 960 residue in all. About a third of the {object:147516} dwarves in {area:1584} drop residue, sometimes several at once; it also sells on the Auction House. {item:11370} or {area:2717} materials at {npc:12944} (next steps) count here too. {npc:12944}'s shop opens at Friendly: {item:16979} 8g, {item:16982} 15g, {item:16983} 16g, {item:17014} 7g, {item:273572} 3g, Transmute Elemental Fire 12g."] = "Friendly to Honored is 6,000 reputation. While you are Friendly Burninate takes Gaining Acceptance instead: 25 reputation for 4 Dark Iron Residue, 240 turn-ins and 960 residue in all. About a third of the Dark Iron dwarves in Blackrock Depths drop residue, sometimes several at once; it also sells on the Auction House. Dark Iron Ore or Molten Core materials at Lokhtos (next steps) count here too. Lokhtos's shop opens at Friendly: Flarecore Gloves 8g, Corehound Boots 15g, Molten Helm 16g, Dark Iron Bracers 7g, Enchant Weapon - Strength 3g, Transmute Elemental Fire 12g.", ["Optional, and it saves every later trip to {npc:12944} the Ring of Law fight. {npc:8888} is a ghost in the middle of {area:1445}: only the dead see him, so die in the mountain and walk to his tomb as a spirit. He sends you after {npc:9056} in {area:1584}, who always drops {item:10999}; place it on {npc:8888}'s monument in the Shrine of Thaurissan and the {item:11000} falls out. {area:1584} is a five-player dungeon: group up."] = "Optional, and it saves every later trip to Lokhtos the Ring of Law fight. Franclorn Forgewright is a ghost in the middle of Blackrock Mountain: only the dead see him, so die in the mountain and walk to his tomb as a spirit. He sends you after Fineous Darkvire in Blackrock Depths, who always drops Ironfel; place it on Franclorn's monument in the Shrine of Thaurissan and the Shadowforge Key falls out. Blackrock Depths is a five-player dungeon: group up.", ["{item:18628}, from {npc:12944}"] = "Thorium Brotherhood Contract, from Lokhtos", ["{npc:12944}'s {area:2717} recipes: fire resistance gear, {object:147516} armour and the Exalted epic weapon plans."] = "Lokhtos's Molten Core recipes: fire resistance gear, Dark Iron armour and the Exalted epic weapon plans." },
			steps = {
				{
					title = "{area:1446}",
					note = "{area:1446} is the scaffolded camp on the north-west rim of the Cauldron, with a flight point. Everyone starts Neutral with the Brotherhood. These seven quests (level 48 to 50) pay 100 reputation each: 700 in all, 800 with the pillow below. In Classic a quest pays less once it is 6 or more levels below you, only 20 each at 60, so do them while you level through {zone:1427} if you can; your first turn-in shows which. {npc:14624}'s {quest:7722} also opens his {item:18942} turn-ins, so it is needed at any level. The numbers in this guide leave out the Legacy perk Diplomat, which adds up to 10%.",
					goals = {
